const themeBtn=document.getElementById("themeToggle");themeBtn.addEventListener("click",()=>{document.body.classList.toggle("light")});const toastBtn=document.getElementById("triggerToast"),toast=document.getElementById("toast");let toastTimeout;toastBtn.addEventListener("click",()=>{toast.classList.add("show"),clearTimeout(toastTimeout),toastTimeout=setTimeout(()=>{toast.classList.remove("show")},3e3)});
